/bin/bash -lc "python3 - <<'PY'
from datetime import datetime, timedelta
from time import perf_counter
from tally import duration, fields, intervals, ledger, schedule
assert duration.parse(' 2W 3d 4H 5m 6S ') == 2*604800+3*86400+4*3600+5*60+6
for value in ['', '1h1h', '1m1h', '3', '1 h', '-1s', '1.5h', 'x1h', '1h"'!'"']:
    try: duration.parse(value)
    except ValueError: pass
    else: raise AssertionError(value)
for n in [0,1,60,3600,604800,123456789]:
    assert duration.parse(duration.format_duration(n)) == n
assert fields.parse_fields(' , a=\" x,\"\"y\"\"=z \", b=, ') == {'a':' x,\"y\"=z ', 'b':''}
for value in ['a=\"x', 'a=1,a=2', '=x', 'abc']:
    try: fields.parse_fields(value)
    except ValueError: pass
    else: raise AssertionError(value)
assert intervals.merge([(4,5),(1,3),(3,4),(0,0)]) == [(1,5)]
assert intervals.free_slots([(-10,2),(8,20)],0,10,6) == [(2,8)]
assert intervals.free_slots([(-10,20)],0,10) == []
assert ledger.bill([(' Ann ','0s'),('ann','0s'),('BOB','0s')],50) == [('Ann',0),('BOB',0)]
assert ledger.bill([('a','1s'),('b','1s')],900) == [('a',1),('b',0)]
for expr, when in [('0 0 L * ?', datetime(2024,2,29)),('0 0 ? * 5L', datetime(2026,5,29)),('0 0 ? * 1#2', datetime(2026,5,11)),('0 0 1 * MON', datetime(2026,5,4)),('0 0 1 * MON', datetime(2026,5,1)),('0 0 * * FRI-MON/2', datetime(2026,5,3))]:
    assert schedule.matches(expr,when), expr
assert not schedule.matches('0 0 * * FRI-MON/2', datetime(2026,5,4))
for expr in ['60 * * * *','* * * *','* * * * * *','*/0 * * * *','0 0 ? ? *','0 0 L/2 * *','0 0 * * MONL','0 0 * * 1#0','0 0 * * 8L','0 0 *, * *','0 0 * * 1,,2','0 0 * * ?/2','@unknown','0 0 * JAN/FRI *','0\\n0 * * *','0 0 l * *']:
    for fn in [schedule.matches,schedule.next_run]:
        try: fn(expr, None)
        except ValueError: pass
        else: raise AssertionError(expr)
for expr in ['*/17 22-2 * * *','2/19 1-4 * * *','0 0 * * FRI-MON','0 0 1 * MON','*/13 * */2 * ?','0 0 * * 7-2/2']:
    after = datetime(2026,5,2,0,0,13)
    expected = after.replace(second=0)+timedelta(minutes=1)
    while not schedule.matches(expr,expected):
        expected += timedelta(minutes=1)
    assert schedule.next_run(expr,after) == expected, expr
start=perf_counter()
assert schedule.next_run('0 0 30 FEB *',datetime(2026,1,1)) is None
elapsed=perf_counter()-start
assert elapsed < .1, elapsed
assert schedule.next_run('* * * * *', datetime.max) is None
assert schedule.next_run('@yearly',datetime(9999,12,31)) is None
print(f'Additional edge checks passed; impossible schedule: {elapsed:.4f}s')
